function nextRefresh(d,c){if(d.disabled)return '已停用';const scheduled=Date.parse(d.nextRefreshAt)||(d.lastSeen?Date.parse(d.lastSeen)+c.intervalSeconds*1000:0);if(!scheduled)return '尚未安排';const value=time(scheduled);return Date.now()>scheduled?`${value}（等待连接）`:value;}
