  const dx=(e.clientX-drag.x)/r.width,dy=(e.clientY-drag.y)/r.height,c={...drag.start};if(drag.resize){const ratio=r.width/r.height/(1200/1600),maxW=Math.min(1-c.x,(1-c.y)/ratio),w=Math.min(maxW,Math.max(Math.min(.1,maxW),Math.max(c.w+dx,(c.h+dy)/ratio)));c.w=w;c.h=w*ratio;}else{c.x=Math.max(0,Math.min(1-c.w,c.x+dx));c.y=Math.max(0,Math.min(1-c.h,c.y+dy));}writeCrop(c);
