// Live simulation: debounce while dragging and drop superseded requests.
let simulateTimer,simulateAbort,simulateURL,simulateGeneration=0;
function cancelSimulation(){clearTimeout(simulateTimer);simulateAbort?.abort();simulateGeneration++;}
$('#photo-dialog').addEventListener('close',cancelSimulation);
function simulate(){cancelSimulation();const generation=simulateGeneration,photoId=editingPhoto?.id,current=()=>generation===simulateGeneration&&editingPhoto?.id===photoId&&$('#photo-dialog')?.open;simulateTimer=setTimeout(async()=>{if(!current())return;simulateAbort=new AbortController();$('#tone-note').textContent='正在按墨水颜色模拟…';try{const r=await fetch(`/api/admin/photos/${photoId}/simulate`,{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify(photoTone($('#photo-form'))),signal:simulateAbort.signal});if(!r.ok)throw Error((await r.json().catch(()=>({}))).error||'模拟失败');const blob=await r.blob();if(!current())return;const url=URL.createObjectURL(blob);if(simulateURL)URL.revokeObjectURL(simulateURL);simulateURL=url;photoPreviewOriginal=false;$('#photo-preview').style.objectFit='fill';$('#photo-preview').src=url;$('#preview-original').classList.remove('active');$('#preview-six').classList.add('active');$('#tone-note').textContent='模拟预览（半分辨率，未保存）。满意后点“保存并更新显示数据”。';}catch(e){if(e.name!=='AbortError'&&current())$('#tone-note').textContent=e.message;}},500);}
{const f=$('#photo-form');f.elements.color.addEventListener('change',()=>{const preset=state.colorLevels[f.elements.color.value];for(const k of ['chroma','brightness','contrast'])f.elements[k].value=preset[k];toneLabels();simulate();});for(const k of ['chroma','brightness','contrast'])f.elements[k].addEventListener('input',()=>{toneLabels();simulate();});f.elements.fit.addEventListener('change',()=>{writeCrop(cropForMode(),false);updateCropMode();simulate();});f.elements.rotation.addEventListener('change',()=>{writeCrop(cropForMode(),false);drawCropSource();simulate();});f.elements.dither.addEventListener('change',simulate);}
$('#photo-form').onsubmit=async e=>{e.preventDefault();const f=e.target,b=$('#save-photo'),split=s=>s.split(/[、,，]/).map(x=>x.trim()).filter(Boolean),collectionIds=selectedCollections(f);if(!collectionIds.length){toast('请至少选择一个收藏集');return;}photoSaving=true;updatePhotoNavigation();$('#delete-photo').disabled=true;b.disabled=true;b.textContent='正在处理…';try{state=await api('/api/admin/photos/'+f.elements.id.value,'PUT',{title:f.elements.title.value,author:f.elements.author.value,contentType:f.elements.contentType.value,subjects:[...f.querySelectorAll('[name="subjects"]:checked')].map(x=>x.value),tags:selectedTags(f),people:split(f.elements.people.value),location:f.elements.location.value,capturedAt:f.elements.capturedAt.value,collectionIds,...photoTone(f),enabled:f.elements.enabled.checked});$('#photo-dialog').close();render();toast('作品已更新');}catch(e){toast(e.message);}finally{photoSaving=false;updatePhotoNavigation();$('#delete-photo').disabled=false;b.disabled=false;b.textContent='保存并更新显示数据';}};
$('#delete-photo').onclick=async()=>{if(!confirm('永久删除这件作品及其显示数据？'))return;try{state=await api('/api/admin/photos/'+$('#photo-form').elements.id.value,'DELETE');$('#photo-dialog').close();render();toast('作品已删除');}catch(e){toast(e.message);}};
function openDevice(deviceId){const d=state.devices.find(d=>d.id===deviceId),f=$('#device-form');if(!d)return;f.elements.id.value=d.id;f.elements.name.value=d.name;f.elements.inherit.checked=d.config===null;f.elements.disabled.checked=d.disabled;fillConfig(f,d.config||state.defaultConfig);toggleInheritance();$('#device-dialog').showModal();}
function toggleInheritance(){const f=$('#device-form');f.querySelectorAll('.config-fields select,.config-fields input').forEach(e=>e.disabled=f.elements.inherit.checked);}$('#device-form').elements.inherit.onchange=toggleInheritance;
async function removeDevice(id,name){if(!confirm(`从列表中删除「${name}」？\n它的下载记录和升级任务会一并删除。\n若这台相框仍在使用，下次联网时会重新出现；要阻止它连接，请改用“停用设备”。`))return false;try{state=await api('/api/admin/devices/'+encodeURIComponent(id),'DELETE');render();toast('已删除相框');return true;}catch(e){toast(e.message);return false;}}
$('[data-device-delete]').onclick=async()=>{const f=$('#device-form');if(await removeDevice(f.elements.id.value,f.elements.name.value))$('#device-dialog').close();};
document.addEventListener('click',e=>{const b=e.target.closest('[data-device-remove]');if(b){const d=state.devices.find(x=>x.id===b.dataset.deviceRemove);if(d)removeDevice(d.id,d.name);}});
// Send the photo being browsed to a frame; the server wakes the frame to sync now.
$('#send-photo').onclick=()=>{if(!editingPhoto)return;const p=state.photos.find(x=>x.id===editingPhoto.id)||editingPhoto,devices=byRecent(state.devices);$('#send-note').textContent=!p.enabled?'这张照片已停止播放，请先勾选“允许在相框中播放”并保存。':photoDirty?'当前窗口里的修改尚未保存，发送的是已保存的显示效果。':'选择相框后会立即通知它同步；若它刚刷新过，会在 3 分钟保护时间后显示。';$('#send-list').innerHTML=devices.length?devices.map(d=>`<button type="button" class="send-device" data-send-device="${esc(d.id)}" ${d.disabled||!p.enabled?'disabled':''}><span><strong>${esc(d.name)}</strong><small>${esc(d.id)} · 上次联网 ${esc(time(d.lastSeen))}</small></span>${tag(d)}</button>`).join(''):'<div class="empty">还没有相框连接到服务器。</div>';$('#send-dialog').showModal();};
$('#send-list').addEventListener('click',async e=>{const b=e.target.closest('[data-send-device]');if(!b||!editingPhoto)return;const d=state.devices.find(x=>x.id===b.dataset.sendDevice);b.disabled=true;try{const r=await api('/api/admin/devices/'+encodeURIComponent(d.id)+'/show','POST',{photoId:editingPhoto.id});state=r;$('#send-dialog').close();render();toast(r.woke?`已发送到 ${d.name}，相框正在同步`:`已发送到 ${d.name}；暂时联系不上相框，将在它下次联网时显示`);}catch(err){toast(err.message);b.disabled=false;}});
$('#device-form').onsubmit=async e=>{e.preventDefault();const f=e.target;try{state=await api('/api/admin/devices/'+encodeURIComponent(f.elements.id.value),'PUT',{name:f.elements.name.value,config:f.elements.inherit.checked?null:getConfig(f),disabled:f.elements.disabled.checked});$('#device-dialog').close();render();toast('已保存，设备下次联网时生效');}catch(e){toast(e.message);}};
