function romCompatible(d,f){return !d.disabled&&d.boardModel===f.boardModel&&d.panelModel===f.panelModel&&d.chipModel===f.chipModel&&d.otaProtocol===f.otaProtocol&&d.otaSlotBytes>=f.bytes;}
const romStatuses={queued:'待下发',offered:'已提供升级任务，等待设备确认',succeeded:'升级成功',failed:'升级失败',cancelled:'已取消'};
function romDeviceHtml(d){const t=d.firmwareTask;return `<div class="help">主板：${esc(d.boardModel||'尚未报告，禁止远程升级')}${t?`<br>ROM ${esc(t.version)} · ${esc(romStatuses[t.status]||t.status)}${t.message?' · '+esc(t.message):''}`:''}</div><button type="button" class="button full" data-rom-device="${esc(d.id)}">升级 ROM</button>${t&&['queued','offered'].includes(t.status)?`<button type="button" class="text-button" data-rom-cancel="${esc(d.id)}">取消升级任务</button>`:''}`;}
function renderRoms(){const list=$('#rom-list');if(!list)return;list.innerHTML=(state.firmwares||[]).length?[...(state.firmwares||[])].reverse().map(f=>`<div class="rom-entry"><strong>${esc(f.version)}</strong><p class="help">${esc(f.boardModel)} · ${esc(f.panelModel)}<br>${bytes(f.bytes)} · ${time(f.createdAt)}</p><details><summary>SHA-256</summary><code style="overflow-wrap:anywhere">${esc(f.sha256)}</code></details></div>`).join(''):'<p class="help">尚未上传 ROM。</p>';}
$('#rom-upload-form').onsubmit=async e=>{e.preventDefault();const file=$('#rom-file').files[0],button=$('#rom-upload');if(!file)return;if(file.size>5*1024*1024){toast('应用 ROM 不能超过 5 MiB');return;}button.disabled=true;button.textContent='正在校验并上传…';try{const buffer=new Uint8Array(await file.arrayBuffer());let binary='';for(let i=0;i<buffer.length;i+=8192)binary+=String.fromCharCode(...buffer.subarray(i,i+8192));state=await api('/api/admin/firmwares','POST',{filename:file.name,data:'data:application/octet-stream;base64,'+btoa(binary)});e.target.reset();render();toast('ROM 已校验并保存，请到相框设备选择下发');}catch(err){toast(err.message);}finally{button.disabled=false;button.textContent='校验并上传 ROM';}};
document.addEventListener('click',async e=>{const open=e.target.closest('[data-rom-device]'),cancel=e.target.closest('[data-rom-cancel]');if(open){const d=state.devices.find(d=>d.id===open.dataset.romDevice),f=$('#rom-deploy-form'),roms=[...(state.firmwares||[])].reverse().filter(r=>romCompatible(d,r)&&r.sha256!==d.firmwareSha256);$('#rom-device-info').textContent=d.name+' · '+(d.boardModel||'主板型号未知');f.elements.deviceId.value=d.id;f.elements.firmwareId.innerHTML=roms.map(r=>`<option value="${esc(r.id)}">${esc(r.version)} · ${bytes(r.bytes)} · ${esc(r.sha256.slice(0,8))}</option>`).join('');f.querySelector('button').disabled=!roms.length;if(!roms.length)$('#rom-device-info').textContent+='。没有可下发的兼容 ROM；旧固件须先通过设备网页或有线方式更新。';$('#rom-dialog').showModal();}if(cancel){if(!confirm('取消尚未安装的升级任务？已开始写入的设备可能继续完成升级。'))return;try{state=await api('/api/admin/devices/'+encodeURIComponent(cancel.dataset.romCancel)+'/firmware','DELETE');render();toast('升级任务已取消');}catch(err){toast(err.message);}}});
$('#rom-deploy-form').onsubmit=async e=>{e.preventDefault();const f=e.target;if(!confirm('确认将所选 ROM 下发到这台相框？设备下次联网时将校验并升级。'))return;try{state=await api('/api/admin/devices/'+encodeURIComponent(f.elements.deviceId.value)+'/firmware','POST',{firmwareId:f.elements.firmwareId.value});$('#rom-dialog').close();render();toast('已下发，等待设备联网领取并校验');}catch(err){toast(err.message);}};
